import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');
import { evolvePath } from "@remotion/paths";

// Module-level font loading ensures deterministic rendering
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type PasswordSyncProps = Record<string, any>;

const getBezierPath = (
  startX: number,
  startY: number,
  endX: number,
  endY: number
) => {
  const midX = (startX + endX) / 2;
  return `M ${startX} ${startY} C ${midX} ${startY}, ${midX} ${endY}, ${endX} ${endY}`;
};

const PasswordSync: React.FC<PasswordSyncProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  vaultName = "Work Portal",
  masterPassword = "MySuperSecret123!",
  accounts = [
    "Personal Email",
    "Banking App",
    "Social Media",
    "Work Portal",
  ],
  accentColor = "#3b82f6",
  lineColor = "#333333",
  cardColor = "#171717",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const actualBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout calculations
  const cx = width * 0.25;
  const cy = height * 0.5;
  const cardW = 400;
  const cardH = 160;

  const ax = width * 0.75;
  const yStart = height * 0.15;
  const yEnd = height * 0.85;
  const totalSpacing = yEnd - yStart;

  // Dynamic scaling for accounts to prevent overlap
  const maxCardH =
    accounts.length > 1 ? totalSpacing / accounts.length - 20 : cardH;
  const accScaleFactor = Math.min(1, maxCardH / cardH);

  const startX = cx + cardW / 2;
  const endX = ax - (cardW / 2) * accScaleFactor;

  // Master Card Animations
  const masterScale = spring({ frame, fps, config: { damping: 12 } });
  const masterTypeCount = interpolate(
    frame,
    [20, 50],
    [0, masterPassword.length],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const isTypingMaster =
    frame >= 20 && Math.floor(masterTypeCount) < masterPassword.length;
  const showCursorMaster = isTypingMaster ? true : frame % 30 < 15;

  return (
    <AbsoluteFill style={{ backgroundColor: actualBgColor, fontFamily: interFamily }}>
      {/* SVG Connections Layer */}
      <AbsoluteFill style={{ zIndex: 1 }}>
        <svg width={width} height={height} style={{ overflow: "visible" }}>
          {accounts.map((_, i) => {
            const startY = cy;
            const endY =
              accounts.length === 1
                ? cy
                : yStart + i * (totalSpacing / (accounts.length - 1));
            const d = getBezierPath(startX, startY, endX, endY);

            const lineProgress = interpolate(
              frame,
              [50 + i * 5, 80 + i * 5],
              [0, 1],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: Easing.bezier(0.25, 1, 0.5, 1),
              }
            );

            // Evolve path to draw the base line
            const evolution = evolvePath(lineProgress, d);

            return (
              <React.Fragment key={`path-${i}`}>
                {/* Base Connector */}
                <path
                  d={d}
                  fill="none"
                  stroke={lineColor}
                  strokeWidth={4}
                  strokeDasharray={evolution.strokeDasharray}
                  strokeDashoffset={evolution.strokeDashoffset}
                  style={{ transition: "none" }}
                />
              </React.Fragment>
            );
          })}
        </svg>
      </AbsoluteFill>

      {/* Master Vault Card */}
      <div
        style={{
          position: "absolute",
          left: cx,
          top: cy,
          transform: `translate(-50%, -50%) scale(${masterScale})`,
          width: cardW,
          height: cardH,
          backgroundColor: cardColor,
          borderRadius: 16,
          border: `2px solid ${lineColor}`,
          display: "flex",
          flexDirection: "column",
          padding: 24,
          justifyContent: "space-between",
          boxShadow: `0 8px 32px ${lineColor}40`,
          zIndex: 10,
          transition: "none",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke={accentColor}
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
            <path d="M7 11V7a5 5 0 0 1 10 0v4" />
          </svg>
          <span
            style={{
              color: textColor,
              fontSize: 24,
              fontWeight: 600,
            }}
          >
            {vaultName}
          </span>
        </div>

        <div
          style={{
            backgroundColor: "rgba(0,0,0,0.2)",
            borderRadius: 8,
            padding: "12px 16px",
            border: `1px solid ${lineColor}`,
            display: "flex",
            alignItems: "center",
            minHeight: 56,
            overflow: "hidden",
            whiteSpace: "nowrap",
          }}
        >
          <span
            style={{
              fontFamily: robotoMonoFamily,
              color: accentColor,
              fontSize: 24,
              letterSpacing: 2,
            }}
          >
            {masterPassword.substring(0, Math.floor(masterTypeCount))}
            {showCursorMaster ? "_" : ""}
          </span>
        </div>
      </div>

      {/* Account Cards */}
      {accounts.map((acc, i) => {
        const endY =
          accounts.length === 1
            ? cy
            : yStart + i * (totalSpacing / (accounts.length - 1));

        const accScale =
          spring({
            frame: frame - 70 - i * 5,
            fps,
            config: { damping: 12 },
          }) * accScaleFactor;

        // Make the typing faster and start closer to when the card pops up
        const typeProgress = interpolate(
          frame,
          [100 + i * 5, 110 + i * 5],
          [0, masterPassword.length],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        const isTypingAcc =
          frame >= 100 + i * 5 && Math.floor(typeProgress) < masterPassword.length;
        const showCursorAcc = isTypingAcc ? true : frame % 30 < 15;

        return (
          <div
            key={`acc-${i}`}
            style={{
              position: "absolute",
              left: ax,
              top: endY,
              transform: `translate(-50%, -50%) scale(${accScale})`,
              width: cardW,
              height: cardH,
              backgroundColor: cardColor,
              borderRadius: 16,
              border: `2px solid ${lineColor}`,
              display: "flex",
              flexDirection: "column",
              padding: 24,
              justifyContent: "space-between",
              boxShadow: `0 8px 32px ${lineColor}40`,
              zIndex: 5,
              transition: "none",
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
              <svg
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                stroke={accentColor}
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                <circle cx="12" cy="7" r="4" />
              </svg>
              <span
                style={{
                  color: textColor,
                  fontSize: 24,
                  fontWeight: 600,
                  whiteSpace: "nowrap",
                  overflow: "hidden",
                  textOverflow: "ellipsis",
                }}
              >
                {acc}
              </span>
            </div>

            <div
              style={{
                backgroundColor: "rgba(0,0,0,0.2)",
                borderRadius: 8,
                padding: "12px 16px",
                border: `1px solid ${lineColor}`,
                display: "flex",
                alignItems: "center",
                minHeight: 56,
                overflow: "hidden",
                whiteSpace: "nowrap",
              }}
            >
              <span
                style={{
                  fontFamily: robotoMonoFamily,
                  color: accentColor,
                  fontSize: 24,
                  letterSpacing: 2,
                }}
              >
                {masterPassword.substring(0, Math.floor(typeProgress))}
                {frame >= 100 + i * 5 && showCursorAcc ? "_" : ""}
              </span>
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default PasswordSync;